/** @jest-environment node */
import { createTaskAgent } from '@/agent/TaskAgent';
import { buildActionQuestions } from '@/agent/request';
import { TASK_REDACTED } from '@/types';
import type { TaskEvent, TaskIdFactory, TaskInputs, TaskObservation } from '@/types';
import {
  deciderOk,
  makeClock,
  makeCompletionDecision,
  makeElement,
  makeFakeDecider,
  makeFakeHost,
  makeObservation,
  makeOutcome,
  makeRequest,
  makeTextField,
} from './helpers/agent-fixtures';
import {
  action,
  approvalResolution,
  chooseCandidate,
  requireStatus,
  setup,
  terminal,
} from './helpers/task-agent-contract';

const characters = (...codes: number[]): string => String.fromCharCode(...codes);
const hasOwn = (value: object | undefined, key: string): boolean =>
  value !== undefined && Object.prototype.hasOwnProperty.call(value, key);
const neutralGoal = 'Complete the task.';

function simpleCompletion(
  secret: string,
  overrides: { readonly observation?: TaskObservation; readonly capture?: boolean } = {}
) {
  const observation =
    overrides.observation ??
    makeObservation({ elements: [makeElement({ label: `Confirm ${secret}` })] });
  const events: TaskEvent[] = [];
  const scenario = setup(
    {
      chooseAction: [
        deciderOk('action', action('CLICK', 't1')),
        deciderOk('action', terminal('DONE')),
      ],
      classifyCommitment: [
        deciderOk('commitment', { commitment: 'NONE', confidence: 0.99, agreement: 'single' }),
      ],
      verifyCompletion: [deciderOk('completion', makeCompletionDecision())],
    },
    { observations: [observation] },
    { onEvent: event => events.push(event) }
  );
  return {
    ...scenario,
    events,
    request: makeRequest({
      goal: neutralGoal,
      inputs: { password: secret },
      options: { captureTrace: overrides.capture ?? true },
    }),
  };
}

describe('coordinator preserves typed structure while redacting text', () => {
  test('issuer-only prior continuation marker remains exact when its fixed wording matches a secret', async () => {
    const secret = characters(105, 115, 115, 117, 105, 110, 103);
    const checkpointKey = `checkpoint-${secret}`;
    const first = setup(
      {
        chooseAction: [deciderOk('action', action('FILL', 't3'))],
        chooseArgument: [deciderOk('argument', { kind: 'none_appropriate', confidence: 0.99 })],
      },
      { observations: [makeObservation({ elements: [makeTextField()] })] },
      { checkpointKey }
    );
    const paused = requireStatus(
      await first.agent.run(
        makeRequest({
          goal: neutralGoal,
          inputs: { password: secret },
          priorEffects: [
            { digest: `dg_${'9'.repeat(32)}`, effects: ['read'], resolution: 'applied' },
          ],
        })
      ),
      'needs_input'
    );
    expect(
      paused.checkpoint.history.some(
        entry => entry.detail === 'Coordinator prior effects require the issuing agent instance.'
      )
    ).toBe(true);
    const other = setup({}, {}, { checkpointKey });
    const resumed = requireStatus(
      await other.agent.resume({
        checkpoint: JSON.parse(JSON.stringify(paused.checkpoint)) as typeof paused.checkpoint,
        inputs: { password: secret },
        resolution: { kind: 'inputs', inputs: {} },
      }),
      'failed'
    );
    expect(resumed.error.code).toBe('CHECKPOINT_INVALID');
    expect(other.fakeHost.calls.capabilities).toHaveLength(0);
    expect(other.fakeHost.calls.observe).toHaveLength(0);
    expect(other.fakeHost.calls.execute).toHaveLength(0);
    expect(other.fakeDecider.calls.chooseAction).toHaveLength(0);
  });

  test('hex fragment identities and input references survive approval checkpoint, JSON resume and DONE', async () => {
    const secret = characters(49, 50, 51, 52);
    const profileKey = `profile${secret}`;
    const path = `${profileKey}.name`;
    let count = 0;
    const ids: TaskIdFactory = prefix =>
      `${prefix}_${secret}${(++count).toString(16).padStart(8, '0')}`;
    const field = makeTextField({
      signature: `sg_${secret}${'a'.repeat(12)}`,
      commitHints: [{ class: 'SEND', basis: 'declared_marker' }],
    });
    const before = makeObservation({
      elements: [field],
      documentId: `doc_${secret}abcdef00`,
      fingerprint: `fp_${secret}_before`,
    });
    const after = makeObservation({
      ...before,
      elements: [{ ...field, state: { ...field.state, value: 'Ada' } }],
      fingerprint: `fp_${secret}_after`,
    });
    const fakeHost = makeFakeHost({ observations: [before, before, after], createId: ids });
    const fakeDecider = makeFakeDecider({
      chooseAction: [
        deciderOk('action', action('FILL', field.id)),
        deciderOk('action', terminal('DONE')),
      ],
      chooseArgument: [
        request => chooseCandidate(request, candidate => candidate.source === 'input'),
      ],
      verifyCompletion: [
        deciderOk('completion', makeCompletionDecision({ evidenceTargetIds: [field.id] })),
      ],
    });
    const agent = createTaskAgent({
      host: fakeHost.host,
      decider: fakeDecider.decider,
      options: {
        createId: ids,
        clock: makeClock(),
        verifier: async () => ({ verdict: 'SATISFIED' }),
      },
    });
    const inputs: TaskInputs = { [profileKey]: { name: 'Ada' }, password: secret };
    const paused = requireStatus(
      await agent.run(makeRequest({ goal: neutralGoal, inputs, options: { captureTrace: true } })),
      'awaiting_approval'
    );
    const checkpoint = JSON.parse(JSON.stringify(paused.checkpoint)) as typeof paused.checkpoint;
    expect(hasOwn(checkpoint.request.inputs, profileKey)).toBe(true);
    expect(
      checkpoint.pending.kind === 'awaiting_approval' &&
        checkpoint.pending.command.operation === 'FILL' &&
        checkpoint.pending.command.value.source === 'input' &&
        checkpoint.pending.command.value.path === path
    ).toBe(true);
    expect(paused.approval.command.target?.signature === field.signature).toBe(true);
    const completed = requireStatus(
      await agent.resume({
        checkpoint,
        inputs: { password: secret },
        resolution: { kind: 'approval', resolution: approvalResolution(paused.approval) },
      }),
      'completed'
    );
    const entry = completed.ledger[0];
    expect(entry?.command.target?.signature === field.signature).toBe(true);
    expect(entry?.scope.snapshotId === fakeHost.calls.execute[0]?.scope.snapshotId).toBe(true);
    expect(completed.sessionId === paused.sessionId && completed.runId === paused.runId).toBe(true);
    expect(
      entry?.command.command.operation === 'FILL' &&
        entry.command.command.value.source === 'input' &&
        entry.command.command.value.path === path
    ).toBe(true);
    expect(completed.completion.verifiedSnapshot.snapshotId.includes(secret)).toBe(true);
    expect(completed.completion.verifiedSnapshot.documentId === before.documentId).toBe(true);
    expect(completed.completion.effected).toBe(true);
    expect(fakeHost.calls.execute).toHaveLength(1);
  });

  test('a common sensitive word never renames label fields in ledger, evidence or events', async () => {
    const secret = characters(108, 97, 98, 101, 108);
    const scenario = simpleCompletion(secret);
    const result = requireStatus(await scenario.agent.run(scenario.request), 'completed');
    expect(hasOwn(result.ledger[0]?.command.target, 'label')).toBe(true);
    expect(result.ledger[0]?.command.target?.label.includes(secret)).toBe(false);
    expect(hasOwn(result.completion.evidence[0], 'label')).toBe(true);
    expect(result.completion.evidence[0]?.label.includes(secret)).toBe(false);
    const executing = scenario.events.find(event => event.type === 'executing');
    expect(executing?.type === 'executing' && hasOwn(executing.command.target, 'label')).toBe(true);
    expect(hasOwn(result.stats.actions, 'applied')).toBe(true);
  });

  test('a sensitive word matching applied preserves effect/status and completion facts', async () => {
    const secret = characters(97, 112, 112, 108, 105, 101, 100);
    const scenario = simpleCompletion(secret);
    const result = requireStatus(await scenario.agent.run(scenario.request), 'completed');
    expect(result.ledger[0]?.status === 'applied' && result.ledger[0].effect === 'applied').toBe(
      true
    );
    expect(result.lastEffect === 'applied' && result.stats.actions.applied === 1).toBe(true);
    expect(result.completion.mode === 'effected' && result.completion.effected === true).toBe(true);
    const executed = scenario.events.find(event => event.type === 'executed');
    expect(
      executed?.type === 'executed' &&
        executed.status === 'applied' &&
        executed.effect === 'applied'
    ).toBe(true);
    expect(
      scenario.fakeDecider.calls.chooseAction[1]?.request.history.some(
        entry => entry.outcome === 'applied' && entry.effect === 'applied'
      )
    ).toBe(true);
  });

  test('short numeric secret preserves numeric metadata and literal task/goal in captured exchanges', async () => {
    const secret = characters(49, 50, 51);
    const numeric = Number(secret);
    const goal = `Complete item ${secret}.`;
    const events: TaskEvent[] = [];
    const exchange = {
      latencyMs: numeric,
      requestBytes: numeric,
      estimatedInputTokens: numeric,
      attemptLog: [{ attempt: 1, status: 200, latencyMs: numeric }],
      usage: { inputTokens: numeric, outputTokens: numeric },
    };
    const { agent } = setup(
      {
        chooseAction: [
          request =>
            deciderOk('action', action('CLICK', 't1'), {
              ...exchange,
              request: buildActionQuestions(request),
            }),
          deciderOk('action', terminal('DONE')),
        ],
        classifyCommitment: [
          deciderOk('commitment', { commitment: 'NONE', confidence: 0.99, agreement: 'single' }),
        ],
        verifyCompletion: [deciderOk('completion', makeCompletionDecision())],
      },
      {
        outcomes: [
          makeOutcome('applied', 'applied', {
            durationMs: numeric,
            readback: { kind: 'click', defaultPrevented: true },
          }),
        ],
      },
      { onEvent: event => events.push(event) }
    );
    const result = requireStatus(
      await agent.run(
        makeRequest({
          goal,
          inputs: { password: secret },
          options: { captureExchanges: true, captureTrace: true },
        })
      ),
      'completed'
    );
    expect(result.goal === goal && result.exchanges[0]?.request?.state.task === goal).toBe(true);
    expect(
      Object.values(result.exchanges[0]?.request?.questions ?? {}).every(
        question => question.instructions.goal === goal
      )
    ).toBe(true);
    expect(
      result.exchanges[0]?.latencyMs === numeric &&
        typeof result.exchanges[0]?.latencyMs === 'number'
    ).toBe(true);
    expect(
      result.exchanges[0]?.requestBytes === numeric &&
        result.exchanges[0]?.usage?.inputTokens === numeric
    ).toBe(true);
    const executed = events.find(event => event.type === 'executed');
    expect(
      executed?.type === 'executed' &&
        executed.durationMs === numeric &&
        typeof executed.durationMs === 'number'
    ).toBe(true);
    expect(
      result.trace?.every(
        event =>
          typeof event.seq === 'number' &&
          typeof event.step === 'number' &&
          typeof event.at === 'number'
      )
    ).toBe(true);
    expect(
      result.ledger[0]?.readback?.kind === 'click' &&
        result.ledger[0].readback.defaultPrevented === true
    ).toBe(true);
  });

  test('checkpoint caller data is scrubbed even under identity/discriminator/goal-shaped keys', async () => {
    const secret = characters(108, 97, 98, 101, 108);
    const { agent } = setup(
      {
        chooseAction: [deciderOk('action', action('FILL', 't3'))],
        chooseArgument: [deciderOk('argument', { kind: 'none_appropriate', confidence: 0.99 })],
      },
      { observations: [makeObservation({ elements: [makeTextField()] })] }
    );
    const result = requireStatus(
      await agent.run(
        makeRequest({
          goal: neutralGoal,
          inputDeclarations: [
            {
              path: 'audit.label',
              sensitive: false,
              bind: { origins: [`https://user:pass@example.test/?token=${secret}#fragment`] },
            },
          ],
          inputs: {
            password: secret,
            audit: {
              id: secret,
              status: secret,
              kind: secret,
              label: secret,
              goal: secret,
              nested: [{ effect: secret }],
              websiteUrl: `https://user:pass@example.test/?token=${secret}#fragment`,
              count: 123,
              enabled: true,
            },
          },
        })
      ),
      'needs_input'
    );
    const inputs = result.checkpoint.request.inputs;
    expect(hasOwn(inputs, 'password')).toBe(false);
    const auditValue = inputs.audit;
    if (auditValue === null || typeof auditValue !== 'object' || Array.isArray(auditValue)) {
      throw new Error('Checkpoint data shape changed.');
    }
    const audit = auditValue as TaskInputs;
    for (const key of ['id', 'status', 'kind', 'label', 'goal']) {
      expect(hasOwn(audit, key)).toBe(true);
      expect(audit[key] === TASK_REDACTED).toBe(true);
    }
    const nested = audit.nested;
    expect(
      Array.isArray(nested) &&
        typeof nested[0] === 'object' &&
        nested[0] !== null &&
        !Array.isArray(nested[0]) &&
        nested[0].effect === TASK_REDACTED
    ).toBe(true);
    expect(audit.count === 123 && typeof audit.count === 'number' && audit.enabled === true).toBe(
      true
    );
    const url = typeof audit.websiteUrl === 'string' ? new URL(audit.websiteUrl) : undefined;
    expect(
      url?.username === '' &&
        url.password === '' &&
        url.hash === '' &&
        url.searchParams.get('token') === TASK_REDACTED
    ).toBe(true);
    const bindingUrl = result.checkpoint.request.inputDeclarations[0]?.bind?.origins?.[0];
    const bound = typeof bindingUrl === 'string' ? new URL(bindingUrl) : undefined;
    expect(
      bound?.username === '' &&
        bound.password === '' &&
        bound.hash === '' &&
        bound.searchParams.get('token') === TASK_REDACTED
    ).toBe(true);
    expect(result.checkpoint.request.goal === neutralGoal).toBe(true);
    expect(JSON.parse(JSON.stringify(result.checkpoint))).toEqual(result.checkpoint);
  });

  test('protocol argument sources and field roles remain typed when they equal a sensitive value', async () => {
    const secret = characters(112, 114, 111, 116, 111, 99, 111, 108);
    const field = makeElement({
      id: 't4',
      kind: 'switch',
      role: 'switch',
      operations: ['SET_CHECKED'],
      state: { checked: true },
    });
    const before = makeObservation({ elements: [field] });
    const after = makeObservation({
      elements: [{ ...field, state: { ...field.state, checked: false } }],
    });
    const { agent } = setup(
      {
        chooseAction: [
          deciderOk('action', action('SET_CHECKED', 't4')),
          deciderOk('action', terminal('DONE')),
        ],
        chooseArgument: [
          request =>
            chooseCandidate(
              request,
              candidate => candidate.source === 'protocol' && candidate.label.includes('unchecked')
            ),
        ],
        classifyCommitment: [
          deciderOk('commitment', { commitment: 'NONE', confidence: 0.99, agreement: 'single' }),
        ],
        verifyCompletion: [
          deciderOk('completion', makeCompletionDecision({ evidenceTargetIds: ['t4'] })),
        ],
      },
      { observations: [before, after] }
    );
    const result = requireStatus(
      await agent.run(
        makeRequest({
          goal: neutralGoal,
          inputs: { password: secret },
          options: { captureTrace: true },
        })
      ),
      'completed'
    );
    expect(result.ledger[0]?.command.argument?.source === 'protocol').toBe(true);
    expect(
      result.ledger[0]?.command.argument?.slot === 'checked' &&
        result.ledger[0]?.command.target?.role === 'switch'
    ).toBe(true);
    expect(
      result.trace?.some(event => event.type === 'argument' && event.source === 'protocol')
    ).toBe(true);
  });
});

/** @jest-environment node */
import { randomUUID } from 'node:crypto';
import { createTypeSafeTaskDecider } from '@/agent/typesafe';
import {
  buildArgumentQuestions,
  buildCompletionQuestions,
  estimateRequestBytes,
} from '@/agent/request';
import { createRemoteTaskHost } from '@/agent/RemoteTaskHost';
import { TASK_BRIDGE_PROTOCOL } from '@/types';
import type {
  TaskBridgeEnvelope,
  TaskBridgeResponse,
  TaskChooseActionRequest,
  TaskChooseArgumentRequest,
  TaskVerifyCompletionRequest,
  TaskTransport,
} from '@/types';
import {
  deciderOk,
  makeCapabilities,
  makeCommandRequest,
  makeElement,
  makeForm,
  makeTextField,
  makeObservation,
} from './helpers/agent-fixtures';

import {
  action,
  approvalResolution,
  requireStatus,
  setup,
  terminal,
} from './helpers/task-agent-contract';

const request: TaskChooseActionRequest = {
  goal: 'Check the current status.',
  step: 0,
  observation: makeObservation(),
  offers: { operations: ['DONE', 'BLOCKED'], targets: {} },
  capabilities: makeCapabilities(),
  inputs: [],
  history: [],
  maxStateBytes: 22000,
};

test.each([200, 400, 401, 429, 500])(
  'credential echoed in a response header never leaves the adapter (HTTP %i)',
  async status => {
    const secret = `probe_${randomUUID().slice(0, 12)}`;
    const decider = createTypeSafeTaskDecider({
      apiKey: secret,
      retry: { maxRetries: 0 },
      http: async () => ({
        ok: status === 200,
        status,
        header: () => secret,
        json: async () => ({}),
      }),
    });
    const result = await decider.chooseAction(request, {
      goal: request.goal,
      step: 0,
      runId: 'run_security',
      callIndex: 1,
    });
    expect(JSON.stringify(result).includes(secret)).toBe(false);
    expect(result.exchange?.requestId).toBeUndefined();
    expect(result.exchange?.attemptLog.every(attempt => attempt.requestId === undefined)).toBe(
      true
    );
  }
);

test('a credential in caller goal or model config is rejected before the HTTP boundary', async () => {
  const secret = `probe_${randomUUID().slice(0, 12)}`;
  const http = jest.fn();
  const decider = createTypeSafeTaskDecider({ apiKey: secret, http });
  const goal = `Check ${secret}`;
  const result = await decider.chooseAction(
    { ...request, goal },
    { goal, step: 0, runId: 'run_security', callIndex: 1 }
  );
  expect(result.ok).toBe(false);
  expect(http).not.toHaveBeenCalled();
  expect(JSON.stringify(result).includes(secret)).toBe(false);
});

test('a host advertising no cancellation waits for the truthful execute outcome', async () => {
  const observation = makeObservation();
  const command = makeCommandRequest();
  const capabilities = makeCapabilities({ protocol: TASK_BRIDGE_PROTOCOL, cancellation: 'none' });
  const calls: string[] = [];
  let finish: (response: TaskBridgeResponse<'execute'>) => void = () => undefined;
  const pending = new Promise<TaskBridgeResponse<'execute'>>(resolve => {
    finish = resolve;
  });
  const response = (envelope: TaskBridgeEnvelope, value: unknown): TaskBridgeResponse =>
    ({
      protocol: TASK_BRIDGE_PROTOCOL,
      callId: envelope.callId,
      documentId: observation.documentId,
      method: envelope.method,
      ok: true,
      value,
    }) as TaskBridgeResponse;
  const transport: TaskTransport = {
    concurrent: true,
    invoke: async envelope => {
      calls.push(envelope.method);
      if (envelope.method === 'hello')
        return {
          kind: 'response',
          response: response(envelope, {
            documentId: observation.documentId,
            url: observation.url,
            origin: observation.origin,
            ready: true,
            isTop: true,
            capabilities,
          }),
        };
      if (envelope.method === 'execute')
        return {
          kind: 'response',
          response: await pending.then(value => ({ ...value, callId: envelope.callId })),
        };
      return { kind: 'response', response: response(envelope, null) };
    },
  };
  const host = createRemoteTaskHost({ transport, cancelGraceMs: 1 });
  expect(await host.capabilities()).toMatchObject({ ok: true, value: { cancellation: 'none' } });
  const controller = new AbortController();
  const execution = host.execute(command, controller.signal);
  await new Promise(resolve => setTimeout(resolve, 5));
  controller.abort();
  await new Promise(resolve => setTimeout(resolve, 10));
  expect(calls).not.toContain('cancel');
  finish({
    protocol: TASK_BRIDGE_PROTOCOL,
    callId: 'req_test',
    documentId: observation.documentId,
    method: 'execute',
    ok: true,
    value: { requestId: command.requestId, status: 'applied', effect: 'applied', durationMs: 15 },
  });
  expect(await execution).toMatchObject({ status: 'applied', effect: 'applied' });
  await host.dispose();
});

test.each(['agreed', 'disagreed'] as const)(
  'a low-confidence commitment keeps its explicit class (%s)',
  async agreement => {
    const scenario = setup({
      chooseAction: [
        deciderOk('action', action('CLICK', 't1')),
        deciderOk('action', terminal('BLOCKED')),
      ],
      classifyCommitment: [
        deciderOk('commitment', { commitment: 'DELETE', confidence: 0.1, agreement }),
      ],
    });
    const result = await scenario.agent.run({
      goal: 'Remove the test item.',
      authorization: { effects: ['delete'] },
    });
    expect(scenario.fakeHost.calls.execute).toHaveLength(1);
    expect(result.ledger[0]?.effects).toContain('delete');
    expect(result.ledger[0]?.effects).not.toContain('other_commitment');
    expect(Object.keys(scenario.fakeHost.calls.execute[0]?.scope ?? {}).sort()).toEqual([
      'documentId',
      'sessionId',
      'snapshotId',
    ]);
  }
);

test('a same-origin form destination change requires a fresh approval', async () => {
  const target = makeElement({ formId: 'f1' });
  const first = makeObservation({
    elements: [target],
    forms: [makeForm({ id: 'f1', action: 'https://shop.example.test/first', fieldIds: [] })],
  });
  const second = {
    ...first,
    forms: [makeForm({ id: 'f1', action: 'https://shop.example.test/second', fieldIds: [] })],
  };
  const scenario = setup(
    {
      chooseAction: [
        deciderOk('action', action('CLICK', 't1')),
        deciderOk('action', action('CLICK', 't1')),
      ],
      classifyCommitment: [
        deciderOk('commitment', { commitment: 'SEND', confidence: 0.99, agreement: 'single' }),
        deciderOk('commitment', { commitment: 'SEND', confidence: 0.99, agreement: 'single' }),
      ],
    },
    { observations: [first, second] }
  );
  const paused = requireStatus(
    await scenario.agent.run({ goal: 'Send the test form.' }),
    'awaiting_approval'
  );
  expect(paused.approval.context.structural.destination?.action).toBe(
    'https://shop.example.test/first'
  );
  const resumed = await scenario.agent.resume({
    checkpoint: paused.checkpoint,
    resolution: { kind: 'approval', resolution: approvalResolution(paused.approval) },
  });
  expect(resumed.status).toBe('awaiting_approval');
  expect(scenario.fakeHost.calls.execute).toHaveLength(0);
  if (resumed.status === 'awaiting_approval') {
    expect(resumed.approval.contextDigest).not.toBe(paused.approval.contextDigest);
    expect(resumed.approval.context.structural.destination?.action).toBe(
      'https://shop.example.test/second'
    );
  }
});

test('argument requests trim candidate criteria to the configured byte budget', () => {
  const target = makeTextField();
  const argument: TaskChooseArgumentRequest = {
    goal: 'Set the name.',
    step: 1,
    observation: makeObservation({ elements: [target] }),
    operation: 'FILL',
    target,
    slot: 'value',
    inputs: [],
    history: [],
    maxStateBytes: 22000,
    candidates: Array.from({ length: 50 }, (_, index) => ({
      id: `c${index + 1}`,
      source: 'input' as const,
      label: 'Candidate name ' + index,
      preview: 'ordinary value '.repeat(5) + index,
      sensitive: false,
    })),
  };
  const set = buildArgumentQuestions(argument, { maxRequestBytes: 2000 });
  expect(estimateRequestBytes(set, 'jev-1.13.0')).toBeLessThanOrEqual(2000);
  const choices = Object.keys(set.questions['argument']?.criteria ?? {});
  expect(choices).toContain('NONE_APPROPRIATE');
  expect(choices.length).toBeGreaterThanOrEqual(2);
  expect(choices.length).toBeLessThan(51);
  expect(set.questions['argument']?.instructions).toMatchObject({
    goal: argument.goal,
    target: target.id,
  });
});

test('diverged non-sensitive observations survive the verifier projection', () => {
  const expected = [
    {
      label: 'Name',
      kind: 'field_value' as const,
      expected: 'Original',
      observed: 'Changed',
      sensitive: false,
      status: 'diverged' as const,
    },
  ];
  const target = makeTextField();
  const verify: TaskVerifyCompletionRequest = {
    goal: 'Check the name.',
    step: 1,
    observation: makeObservation({ elements: [target] }),
    inputs: [],
    evidenceSlots: 1,
    history: [],
    collectedEvidence: [],
    expected,
    maxStateBytes: 22000,
  };
  const set = buildCompletionQuestions(verify);
  const serialized = JSON.stringify(set.state);
  expect(serialized).toContain('Changed');
  expect(serialized).toContain('Original');
  const sensitive = buildCompletionQuestions({
    ...verify,
    expected: expected.map(item => ({ ...item, sensitive: true, expected: true })),
  });
  expect(JSON.stringify(sensitive.state)).not.toContain('Changed');
});

import { randomBytes } from 'crypto';
import { readFileSync } from 'fs';
import { resolve } from 'path';
import { AutomationEngine } from '@/core/AutomationEngine';
import { ContextCapture } from '@/context/ContextCapture';
import { EnhancedFormDetector } from '@/forms/EnhancedFormDetector';
import { FormRegistry } from '@/forms/FormRegistry';
import { createRedactor } from '@/utils/redact';
import type {
  ActionCommand,
  AutomationConfig,
  AutomationEvent,
  EventType,
  ExecutionResult,
  FormLibrary,
  MutationGuard,
  Redactor,
} from '@/types';
import { DEFAULT_CONFIG, TASK_REDACTED } from '@/types';
import { installLayoutStubs, mountHtml, resetDom } from './helpers/domHarness';

type FakeMethod = 'click' | 'fill' | 'wait';
type FakeHandler = (options: unknown, guard: MutationGuard) => Promise<unknown>;
type FakeDom = { readonly handlers: Partial<Record<FakeMethod, FakeHandler>> };
type Recorded = { readonly __recorded: Error[] };

// Every AutomationError the library constructs during a test is recorded, so the thrown messages and
// contexts can be scanned even though the executor never lets them escape.
jest.mock('@/types', () => {
  const actual = jest.requireActual('@/types') as typeof import('@/types');
  const recorded: Error[] = [];
  class RecordingError extends actual.AutomationError {
    constructor(
      message: string,
      code: ConstructorParameters<typeof actual.AutomationError>[1],
      context?: ConstructorParameters<typeof actual.AutomationError>[2]
    ) {
      super(message, code, context);
      recorded.push(this);
    }
  }
  return { ...actual, AutomationError: RecordingError, __recorded: recorded };
});

jest.mock('@/actions/DOMActions', () => {
  const fakeDom: FakeDom = { handlers: {} };
  const dispatch = async (
    method: FakeMethod,
    options: unknown,
    guard: MutationGuard
  ): Promise<unknown> => {
    const handler = fakeDom.handlers[method];
    if (handler) {
      return handler(options, guard);
    }
    if (method !== 'wait') {
      guard.commit();
    }
    return undefined;
  };
  class DOMActions {
    public initialize(): void {}
    public dispose(): void {}
    public click(options: unknown, guard: MutationGuard): Promise<unknown> {
      return dispatch('click', options, guard);
    }
    public fill(options: unknown, guard: MutationGuard): Promise<unknown> {
      return dispatch('fill', options, guard);
    }
    public wait(options: unknown, guard: MutationGuard): Promise<unknown> {
      return dispatch('wait', options, guard);
    }
  }
  return { DOMActions, __fakeDom: fakeDom };
});

const fakeDom = (jest.requireMock('@/actions/DOMActions') as { __fakeDom: FakeDom }).__fakeDom;
const recorded = (jest.requireMock('@/types') as unknown as Recorded).__recorded;

const ALL_EVENTS: readonly EventType[] = [
  'form_registered',
  'form_unregistered',
  'form_filled',
  'form_submitted',
  'action_started',
  'action_completed',
  'action_failed',
  'context_captured',
  'screenshot_taken',
];

const unique = (tag: string): string => `${tag}-${randomBytes(8).toString('hex')}`;

function show(value: unknown): string {
  if (value instanceof Element) {
    return value.outerHTML;
  }
  if (value instanceof Error) {
    return `${value.name}: ${value.message}\n${value.stack ?? ''}\n${show((value as { context?: unknown }).context)}`;
  }
  if (value !== null && typeof value === 'object') {
    try {
      return JSON.stringify(value, (_key, inner: unknown) =>
        inner instanceof Error ? show(inner) : inner
      );
    } catch {
      return Object.prototype.toString.call(value);
    }
  }
  return String(value);
}

let consoleSpies: jest.SpyInstance[] = [];
let errorMark = 0;

function consoleText(): string {
  return consoleSpies
    .flatMap(spy => spy.mock.calls as unknown[][])
    .map(call => call.map(show).join(' '))
    .join('\n');
}

function consoleCallCount(): number {
  return consoleSpies.reduce((total, spy) => total + spy.mock.calls.length, 0);
}

function thrownText(): string {
  return recorded.slice(errorMark).map(show).join('\n');
}

beforeEach(() => {
  consoleSpies = (['info', 'log', 'warn', 'error', 'debug'] as const).map(method =>
    jest.spyOn(console, method).mockImplementation(() => undefined)
  );
  errorMark = recorded.length;
  for (const key of Object.keys(fakeDom.handlers)) {
    delete fakeDom.handlers[key as FakeMethod];
  }
  document.body.innerHTML = '';
});

afterEach(() => {
  jest.restoreAllMocks();
  jest.useRealTimers();
});

type Mode = { readonly name: string; readonly useRedactor: boolean; readonly declare: boolean };
const MODES: readonly Mode[] = [
  { name: 'with a redactor only', useRedactor: true, declare: false },
  { name: 'with sensitiveParameters only', useRedactor: false, declare: true },
  { name: 'with both', useRedactor: true, declare: true },
];

describe.each(MODES)('executor and engine output $name', mode => {
  let secret: string;
  let redactor: Redactor | undefined;
  let engine: AutomationEngine;
  let events: AutomationEvent[];
  const results: ExecutionResult[] = [];

  const command = (
    type: ActionCommand['type'],
    parameters: Record<string, string>,
    sensitiveNames: readonly string[] = ['value']
  ): ActionCommand => ({
    type,
    parameters,
    ...(mode.declare ? { sensitiveParameters: sensitiveNames } : {}),
  });

  async function run(
    action: ActionCommand,
    options?: Parameters<AutomationEngine['executeAction']>[1]
  ): Promise<ExecutionResult> {
    const result = await engine.executeAction(action, options);
    results.push(result);
    return result;
  }

  function leaks(): string[] {
    const haystacks: Record<string, string> = {
      events: show(events),
      results: show(results),
      console: consoleText(),
      thrown: thrownText(),
    };
    return Object.keys(haystacks).filter(name => (haystacks[name] as string).includes(secret));
  }

  beforeEach(() => {
    secret = unique('Sx9-secret');
    redactor = mode.useRedactor ? createRedactor({ secrets: [secret] }) : undefined;
    const config: Partial<AutomationConfig> = { screenshotOnError: false, redactor };
    engine = new AutomationEngine(config);
    engine.initialize();
    events = [];
    results.length = 0;
    for (const type of ALL_EVENTS) {
      engine.addEventListener(type, event => events.push(event));
    }
    document.body.innerHTML = '<input id="pw" placeholder="Password"><button id="go">Go</button>';
  });

  afterEach(() => {
    engine.dispose();
  });

  test('a successful fill emits the marker instead of the value and keeps the other parameters', async () => {
    const result = await run(
      command('fill', { selector: 'Password', value: secret, description: 'The password box' })
    );

    expect(result.success).toBe(true);
    const started = events.find(event => event.type === 'action_started');
    const parameters = started?.data?.parameters as Record<string, string>;
    expect(parameters.value).toBe(redactor?.replacement ?? TASK_REDACTED);
    expect(parameters.selector).toBe('Password');
    expect(parameters.description).toBe('The password box');
    expect(events.map(event => event.type)).toContain('action_completed');
    expect(leaks()).toEqual([]);
  });

  test('a DOM layer error that echoes the value is scrubbed in the result and in the failure event', async () => {
    fakeDom.handlers.fill = async () => {
      throw new Error(`Option not found in select: ${secret}`);
    };

    const result = await run(command('fill', { selector: 'Password', value: secret }));

    expect(result.success).toBe(false);
    expect(result.error).toContain('Option not found in select');
    expect(result.error).not.toContain(secret);
    const failed = events.find(event => event.type === 'action_failed');
    expect(failed?.data?.error).toContain('Option not found in select');
    expect(leaks()).toEqual([]);
  });

  test('a thrown AutomationError with the value in its message is scrubbed too', async () => {
    const { AutomationError } = jest.requireMock('@/types') as typeof import('@/types');
    let thrownByFake: Error | undefined;
    fakeDom.handlers.click = async () => {
      thrownByFake = new AutomationError(`Click failed near ${secret}`, 'EXECUTION_FAILED');
      throw thrownByFake;
    };

    const result = await run(command('click', { selector: '#go', value: secret }));
    // The stand-in layer itself is the one place allowed to hold the value; the library must not copy it.
    recorded.splice(recorded.indexOf(thrownByFake as Error), 1);

    expect(result.errorCode).toBe('EXECUTION_FAILED');
    expect(result.error).toContain('Click failed near');
    expect(result.error).not.toContain(secret);
    expect(leaks()).toEqual([]);
  });

  test('timeout, cancellation, validation and a missing target never echo the value', async () => {
    fakeDom.handlers.fill = async () => {
      await new Promise<void>(resolveSleep => setTimeout(resolveSleep, 150));
    };
    const timedOut = await run({
      ...command('fill', { selector: 'Password', value: secret }),
      timeout: 20,
    });
    const controller = new AbortController();
    controller.abort();
    const cancelled = await run(command('fill', { selector: 'Password', value: secret }), {
      signal: controller.signal,
    });
    const noTarget = await run(command('fill', { value: secret, strict: 'true' }));
    const invalid = await run(
      command('click', { strict: 'true', selector: '#go', clickCount: secret }, ['clickCount']),
      { strict: true }
    );
    const strictFill = await run(
      command('fill', { selector: 'Password', value: secret, strict: 'true' }),
      { strict: true }
    );

    expect([
      timedOut.errorCode,
      cancelled.errorCode,
      noTarget.errorCode,
      invalid.errorCode,
    ]).toEqual(['EXECUTION_TIMEOUT', 'EXECUTION_CANCELLED', 'INVALID_ACTION', 'VALIDATION_FAILED']);
    expect(strictFill.success).toBe(true);
    expect(leaks()).toEqual([]);
  });

  test('a missing or malformed argument never carries the action into a message or context', async () => {
    const missingValue = await run(command('fill', { selector: secret }, ['selector']));
    const badPayload = await run(command('fillForm', { fields: `{"pw":"${secret}"` }, ['fields']));
    const noKey = await run(command('press', { selector: secret }, ['selector']));
    const noUrl = await run(command('navigate', { waitForLoad: secret }, ['waitForLoad']));

    for (const result of [missingValue, badPayload, noKey, noUrl]) {
      expect(result.success).toBe(false);
      expect(result.errorCode).toBe('VALIDATION_FAILED');
    }
    expect(recorded.slice(errorMark).length).toBeGreaterThan(0);
    for (const error of recorded.slice(errorMark)) {
      const contextKeys = Object.keys((error as { context?: object }).context ?? {});
      expect(contextKeys).not.toContain('action');
    }
    expect(leaks()).toEqual([]);
  });

  test('a result string that carries the value is scrubbed in the completion event, large strings are left alone', async () => {
    const capture = jest
      .spyOn(ContextCapture.prototype, 'captureScreenshot')
      .mockResolvedValueOnce(`data:image/png;base64,${secret}`)
      .mockResolvedValueOnce(`data:${'A'.repeat(30000)}`);

    const small = await run(command('screenshot', { value: secret }));
    const large = await run(command('screenshot', { value: secret }));
    const completed = events.filter(event => event.type === 'action_completed');

    expect([small.success, large.success]).toEqual([true, true]);
    expect(show(completed[0]?.data)).not.toContain(secret);
    expect(show(completed[0]?.data)).toContain('data:image/png;base64,');
    expect((completed[1]?.data?.result as string).length).toBe(30005);
    capture.mockRestore();
  });

  test('a parameters bag that is not an object is rejected without echoing it', async () => {
    const noBag = await run({ type: 'fill', parameters: secret } as unknown as ActionCommand);

    expect(noBag).toMatchObject({ success: false, errorCode: 'VALIDATION_FAILED', effect: 'none' });
    expect(leaks()).toEqual([]);
  });
});

