/** @jest-environment node */
import { createTaskAgent } from '@/agent/TaskAgent';
import type { TaskExecutionEffect, TaskExecutionOutcome, TaskHost } from '@/types';
import {
  counterIds,
  deciderFail,
  deciderOk,
  makeCapabilities,
  makeClock,
  makeManualClock,
  makeOutcome,
  makeRequest,
} from './helpers/agent-fixtures';
import { action, deferred, requireStatus, setup, terminal } from './helpers/task-agent-contract';

function abortReached(signal?: AbortSignal): Promise<void> {
  return new Promise(resolve => {
    if (signal === undefined) throw new Error('operation did not receive cancellation signal');
    if (signal.aborted) resolve();
    else signal.addEventListener('abort', () => resolve(), { once: true });
  });
}

const routine = deciderOk('commitment', {
  commitment: 'NONE' as const,
  confidence: 0.99,
  agreement: 'single' as const,
});

describe('TaskAgent cancellation and budget accounting', () => {
  test('pre-aborted request returns cancelled idle without touching the page', async () => {
    const controller = new AbortController();
    controller.abort();
    const { agent, fakeHost } = setup({});
    const result = requireStatus(await agent.run(makeRequest(), controller.signal), 'cancelled');
    expect(result.during).toBe('idle');
    expect(result.lastEffect).toBe('none');
    expect(result.unresolvedUncertain).toEqual([]);
    expect(fakeHost.calls.execute).toHaveLength(0);
    expect(fakeHost.calls.release).toEqual([result.sessionId]);
  });

  test('abort during observation is forwarded to host and never claims completion', async () => {
    const entered = deferred<void>();
    const controller = new AbortController();
    const fixture = setup({});
    const host: TaskHost = {
      ...fixture.fakeHost.host,
      observe: async (_request, signal) => {
        entered.resolve();
        await abortReached(signal);
        return { ok: false, error: { code: 'CANCELLED', message: 'aborted', retryable: false } };
      },
    };
    const agent = createTaskAgent({
      host,
      decider: fixture.fakeDecider.decider,
      options: { clock: makeClock(), createId: counterIds() },
    });
    const running = agent.run(makeRequest(), controller.signal);
    await entered.promise;
    controller.abort();
    const result = requireStatus(await running, 'cancelled');
    expect(result.during).toBe('observation');
    expect(result.lastEffect).toBe('none');
    expect('completion' in result).toBe(false);
    expect(fixture.fakeHost.calls.release).toEqual([result.sessionId]);
  });

  test('cancel(runId) aborts only the active named run during a decision', async () => {
    const entered = deferred<void>();
    const fixture = setup({});
    const fakeHost = fixture.fakeHost;
    const agent = createTaskAgent({
      host: fakeHost.host,
      decider: {
        ...fixture.fakeDecider.decider,
        chooseAction: async (_request, context) => {
          entered.resolve();
          await abortReached(context.signal);
          return deciderFail('CANCELLED');
        },
      },
    });
    const running = agent.run(makeRequest({ runId: 'run_000000000009' }));
    await entered.promise;
    expect(agent.cancel('run_000000000008')).toBe(false);
    expect(agent.cancel('run_000000000009')).toBe(true);
    const result = requireStatus(await running, 'cancelled');
    expect(result.during).toBe('decision');
    expect(result.lastEffect).toBe('none');
    expect(agent.cancel()).toBe(false);
    expect(fakeHost.calls.execute).toHaveLength(0);
    expect(fakeHost.calls.release).toEqual([result.sessionId]);
  });

  test.each(['none', 'applied', 'uncertain'] as const)(
    'action cancellation retains host effect %s and uncertain checkpoint truthfully',
    async (effect: TaskExecutionEffect) => {
      const entered = deferred<void>();
      const controller = new AbortController();
      const fixture = setup({
        chooseAction: [deciderOk('action', action('CLICK', 't1'))],
        classifyCommitment: [routine],
      });
      let executions = 0;
      const host: TaskHost = {
        ...fixture.fakeHost.host,
        execute: async (request, signal) => {
          executions += 1;
          entered.resolve();
          await abortReached(signal);
          return effect === 'uncertain'
            ? makeOutcome('uncertain', effect, {
                requestId: request.requestId,
                code: 'EXECUTION_CANCELLED',
              })
            : makeOutcome('failed', effect, {
                requestId: request.requestId,
                code: 'EXECUTION_CANCELLED',
              });
        },
      };
      const agent = createTaskAgent({
        host,
        decider: fixture.fakeDecider.decider,
        options: { clock: makeClock(), createId: counterIds() },
      });
      const running = agent.run(makeRequest(), controller.signal);
      await entered.promise;
      controller.abort();
      const result = requireStatus(await running, 'cancelled');
      expect(result.during).toBe('action');
      expect(result.lastEffect).toBe(effect);
      expect(result.ledger).toHaveLength(1);
      expect(result.unresolvedUncertain).toEqual(effect === 'uncertain' ? [1] : []);
      expect(result.checkpoint?.pending.kind).toBe(
        effect === 'uncertain' ? 'uncertain_effect' : undefined
      );
      expect('completion' in result).toBe(false);
      expect(executions).toBe(1);
      expect(fixture.fakeHost.calls.release).toEqual([result.sessionId]);
    }
  );

  test('cancellation none waits for the in-flight host outcome before resolving cancelled', async () => {
    const entered = deferred<void>();
    const outcome = deferred<TaskExecutionOutcome>();
    const fixture = setup(
      { chooseAction: [deciderOk('action', action('CLICK', 't1'))], classifyCommitment: [routine] },
      { capabilities: makeCapabilities({ cancellation: 'none' }) }
    );
    const host: TaskHost = {
      ...fixture.fakeHost.host,
      execute: async request => {
        entered.resolve();
        const result = await outcome.promise;
        return { ...result, requestId: request.requestId };
      },
    };
    const agent = createTaskAgent({ host, decider: fixture.fakeDecider.decider });
    let settled = false;
    const running = agent.run(makeRequest()).then(result => {
      settled = true;
      return result;
    });
    await entered.promise;
    expect(agent.cancel()).toBe(true);
    await Promise.resolve();
    await Promise.resolve();
    expect(settled).toBe(false);
    outcome.resolve(makeOutcome('applied', 'applied'));
    const result = requireStatus(await running, 'cancelled');
    expect(result.lastEffect).toBe('applied');
    expect(result.during).toBe('action');
  });

  test.each([
    ['maxSteps' as const, 1],
    ['maxModelCalls' as const, 1],
  ])('%s refuses work N+1 while allowing N calls', async (budget, limit) => {
    const { agent, fakeDecider, fakeHost } = setup({
      chooseAction: [deciderOk('action', terminal('DONE'))],
      verifyCompletion: [
        deciderOk('completion', {
          verdict: 'NOT_SATISFIED',
          confidence: 0.99,
          evidenceTargetIds: ['t1'],
        }),
      ],
    });
    const result = requireStatus(
      await agent.run(makeRequest({ options: { budgets: { [budget]: limit } } })),
      'blocked'
    );
    expect(result.reason).toBe('BUDGET_EXHAUSTED');
    expect(result.budget).toBe(budget);
    expect(fakeDecider.calls.chooseAction).toHaveLength(1);
    expect(fakeDecider.calls.verifyCompletion).toHaveLength(budget === 'maxSteps' ? 1 : 0);
    expect(fakeHost.calls.release).toEqual([result.sessionId]);
  });

  test('wall-time budget blocks only after active elapsed time exceeds the limit', async () => {
    const clock = makeManualClock();
    const { agent, fakeDecider } = setup(
      {
        chooseAction: [
          () => {
            clock.advance(11);
            return deciderOk('action', terminal('DONE'));
          },
        ],
        verifyCompletion: [],
      },
      {},
      { clock: clock.now }
    );
    const result = requireStatus(
      await agent.run(makeRequest({ options: { budgets: { maxWallTimeMs: 10 } } })),
      'blocked'
    );
    expect(result.reason).toBe('BUDGET_EXHAUSTED');
    expect(result.budget).toBe('maxWallTimeMs');
    expect(fakeDecider.calls.verifyCompletion).toHaveLength(0);
  });

  test('release errors remain best effort and do not replace the terminal result', async () => {
    const fixture = setup({ chooseAction: [deciderOk('action', terminal('BLOCKED'))] });
    const release = jest.fn(async () => {
      throw new Error('release failure');
    });
    const agent = createTaskAgent({
      host: { ...fixture.fakeHost.host, release },
      decider: fixture.fakeDecider.decider,
    });
    const result = requireStatus(await agent.run(makeRequest()), 'blocked');
    expect(result.reason).toBe('MODEL_BLOCKED');
    expect(release).toHaveBeenCalledTimes(1);
    expect(fixture.fakeHost.calls.dispose).toHaveLength(0);
  });
});

import { createResearchGuide } from '../src/guide/ResearchGuide';
import { observePage, resetGuideCache } from '../src/guide/observe';
import { createTypeSafeDecider } from '../src/guide/typesafe';
import type { GuideDecideResult, GuideHttp, SystemOneRequest } from '../src/types';

function element(tag: string, text: string, top = 200): HTMLElement {
  const node = document.createElement(tag);
  node.textContent = text;
  node.getBoundingClientRect = (): DOMRect =>
    ({
      x: 20,
      y: top,
      top,
      left: 20,
      right: 320,
      bottom: top + 40,
      width: 300,
      height: 40,
      toJSON: (): object => ({}),
    }) as DOMRect;
  document.body.append(node);
  return node;
}
function distribution(
  criteria: Readonly<Record<string, unknown>>,
  choice: string
): Record<string, number> {
  return Object.fromEntries(Object.keys(criteria).map(key => [key, key === choice ? 1 : 0]));
}
function target(request: SystemOneRequest, operation: string, text: string): string {
  return (
    Object.entries(request.questions[`${operation.toLowerCase()}_target`]?.criteria ?? {}).find(
      ([, value]) => typeof value === 'object' && value.element?.includes(text)
    )?.[0] ?? ''
  );
}
const execute = async (
  step: { operation?: string },
  node: HTMLElement | undefined
): Promise<void> => {
  if (step.operation === 'CLICK') node?.click();
};
const finishYes: GuideDecideResult = {
  ok: true,
  operation: 'DONE',
  confidence: 1,
  answer: 'YES',
  answerConfidence: 1,
};

describe('single-question Jev investigation', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
    window.history.replaceState(null, '', '/');
    resetGuideCache();
  });

  test('the model chooses navigation and evidence from one unchanged question, with no supplied destinations or quotes', async () => {
    const link = element('a', 'Help center');
    link.setAttribute('href', '/help');
    link.addEventListener('click', event => {
      event.preventDefault();
      window.history.pushState(null, '', '/help');
      document.body.innerHTML = '';
      element('h2', 'Invoices can be exported as CSV');
    });
    const goal = 'Does this service support exporting invoices?';
    const requests: SystemOneRequest[] = [];
    const http: GuideHttp = async (url, init) => {
      expect(url).toBe('https://api.typesafe.ai/v1/systemone');
      expect(init.headers.Authorization).toBe('Bearer fixture-key');
      const request = JSON.parse(init.body) as SystemOneRequest;
      requests.push(request);
      const operation =
        requests.length === 1 ? 'CLICK' : requests.length === 2 ? 'HIGHLIGHT' : 'DONE';
      const key = `${operation.toLowerCase()}_target`;
      const choice = target(
        request,
        operation,
        operation === 'CLICK' ? 'Help center' : 'Invoices can'
      );
      return {
        ok: true,
        status: 200,
        json: async (): Promise<unknown> => ({
          model: 'jev-fixture',
          answers: {
            operation: {
              choice: operation,
              confidence: 1,
              probabilities: distribution(request.questions.operation?.criteria ?? {}, operation),
            },
            ...(choice !== ''
              ? {
                  [key]: {
                    choice,
                    confidence: 1,
                    probabilities: distribution(request.questions[key]?.criteria ?? {}, choice),
                  },
                }
              : {}),
            ...(request.questions.answer !== undefined
              ? {
                  answer: {
                    choice: 'YES',
                    confidence: 1,
                    probabilities: distribution(request.questions.answer.criteria, 'YES'),
                  },
                }
              : {}),
          },
        }),
      };
    };
    const guide = createResearchGuide({ execute });
    const result = await guide.run(goal, createTypeSafeDecider({ apiKey: 'fixture-key', http }));
    expect(result).toMatchObject({ ok: true, answer: 'YES', steps: 3 });
    expect(result.evidence.map(item => item.text)).toEqual(['Invoices can be exported as CSV']);
    expect(requests.every(request => request.state.task === goal)).toBe(true);
    expect(requests.every(request => request.questions.operation?.instructions.goal === goal)).toBe(
      true
    );
    expect(requests.every(request => request.state.objective === undefined)).toBe(true);
    const instructions = requests
      .flatMap(request =>
        Object.values(request.questions).map(question => JSON.stringify(question.instructions))
      )
      .join(' ');
    expect(instructions).not.toContain('/help');
    expect(instructions).not.toContain('Invoices can be exported as CSV');
    expect(requests[0]?.questions.operation?.criteria).not.toHaveProperty('DONE');
    expect(requests[2]?.questions.operation?.criteria).toHaveProperty('DONE');
    expect(requests[2]?.state.evidence).toEqual(result.evidence);
    expect(requests[2]?.questions.answer?.instructions.question).toBe(goal);
  });

  test('Jev can finish after one selected passage without a required tour length', async () => {
    element('p', 'Recurring billing is supported');
    let calls = 0;
    const result = await createResearchGuide({ execute }).run(
      'Does the service support recurring billing?',
      async request => {
        calls += 1;
        return calls === 1
          ? {
              ok: true,
              operation: 'HIGHLIGHT',
              targetIndex: target(request, 'HIGHLIGHT', 'Recurring'),
              confidence: 1,
            }
          : finishYes;
      }
    );
    expect(result).toMatchObject({ ok: true, steps: 2, answer: 'YES' });
    expect(result.evidence).toHaveLength(1);
  });

  test('a confident negative answer cannot turn into success', async () => {
    element('p', 'Recurring billing is unavailable');
    let calls = 0;
    const result = await createResearchGuide({ execute }).run(
      'Does the service support recurring billing?',
      async request => {
        calls += 1;
        return calls === 1
          ? {
              ok: true,
              operation: 'HIGHLIGHT',
              targetIndex: target(request, 'HIGHLIGHT', 'Recurring'),
              confidence: 1,
            }
          : { ...finishYes, answer: 'NO' };
      }
    );
    expect(result).toMatchObject({ ok: false, answer: 'NO', status: 'failure' });
  });

  test('an undecided answer cannot turn into success even when Jev chooses DONE', async () => {
    element('p', 'Welcome to our service');
    let calls = 0;
    const result = await createResearchGuide({ execute }).run(
      'Does this service support invoicing?',
      async request => {
        calls += 1;
        return calls === 1
          ? {
              ok: true,
              operation: 'HIGHLIGHT',
              targetIndex: target(request, 'HIGHLIGHT', 'Welcome'),
              confidence: 1,
            }
          : { ...finishYes, answer: 'UNKNOWN' };
      }
    );
    expect(result).toMatchObject({ ok: false, answer: 'UNKNOWN' });
  });

  test('authentication failure cannot execute actions', async () => {
    element('p', 'Recurring billing is supported');
    const apply = jest.fn(async (): Promise<void> => {});
    const http: GuideHttp = async () => ({
      ok: false,
      status: 401,
      json: async (): Promise<unknown> => ({}),
    });
    const result = await createResearchGuide({ execute: apply }).run(
      'Does the service support billing?',
      createTypeSafeDecider({ apiKey: 'invalid-fixture', http })
    );
    expect(result).toMatchObject({ ok: false, error: 'TypeSafe returned HTTP 401' });
    expect(apply).not.toHaveBeenCalled();
  });

  test('cancellation prevents a late model decision from executing', async () => {
