function fingerprintOf(
  content: Pick<TaskObservation, 'url' | 'text' | 'elements' | 'notices'>
): string {
  return fnv1a(
    JSON.stringify([
      content.url,
      content.elements.map(element => [element.signature, element.state]),
      content.notices,
      content.text,
    ])
  );
}

