    ...makeScope(),
    sequence: 1,
    observedAt: FIXTURE_START,
    url,
    origin: originOf(url),
    title: 'Fixture page',
    text: 'Fixture page text',
    page: {
      readyState: 'complete',
      busy: false,
      scroll: { directions: [], top: 0, max: 0 },
